using namespace std;

struct Appliance { int id; string name; string category; int watts; int standby; string efficiency; string priority; string status; };
struct Usage { int id; string name; string start; string end; double hours; int watts; double daily; double peak; };

vector<Appliance> catalogue = {
 {1,"Air Conditioner","Cooling",1500,2,"B","Essential","ON"},{2,"Ceiling Fan","Cooling",75,1,"A","Essential","ON"},{3,"Refrigerator","Kitchen",200,5,"B","Essential","ON"},
 {4,"Washing Machine","Laundry",500,1,"B","Normal","ON"},{5,"LED Bulb","Lighting",9,1,"B","Normal","ON"},{6,"Tube Light","Lighting",40,1,"B","Normal","ON"},
 {7,"Television","Entertainment",100,1,"B","Normal","ON"},{8,"Laptop","Electronics",65,1,"B","Normal","ON"},{9,"Desktop Computer","Electronics",200,1,"B","Normal","ON"},
 {10,"Water Heater / Geyser","Heating",2000,1,"B","Normal","ON"},{11,"Water Pump","Utility",750,1,"B","Normal","ON"},{12,"Microwave Oven","Kitchen",1200,1,"B","Normal","ON"},
 {13,"Electric Iron","Utility",1000,1,"B","Normal","ON"},{14,"Mixer Grinder","Kitchen",500,1,"B","Normal","ON"},{15,"Electric Kettle","Kitchen",1500,1,"B","Normal","ON"},
 {16,"Cooler","Cooling",180,1,"B","Normal","ON"},{17,"Room Heater","Heating",1500,1,"B","Normal","ON"},{18,"Wi-Fi Router","Electronics",12,1,"B","Normal","ON"},
 {19,"Dishwasher","Kitchen",1200,1,"B","Normal","ON"},{20,"Electric Vehicle Charger","Transport",3000,1,"B","Normal","ON"}
};
vector<Usage> usages;
bool hasSolar=false;
int nextId=1;
const double TARIFF=8.0;

string trim(const string &s){ size_t a=s.find_first_not_of(" \r\n\t"); if(a==string::npos)return ""; size_t b=s.find_last_not_of(" \r\n\t"); return s.substr(a,b-a+1); }
string jsonEscape(const string &s){ string o; for(char c:s){ if(c=='"'||c=='\\'){o+='\\';o+=c;} else if(c=='\n')o+="\\n"; else if((unsigned char)c>=32)o+=c; } return o; }
string urlDecode(const string &s){ string o; for(size_t i=0;i<s.size();i++){ if(s[i]=='+')o+=' '; else if(s[i]=='%'&&i+2<s.size()){ string h=s.substr(i+1,2); o+=(char)strtol(h.c_str(),0,16); i+=2; } else o+=s[i]; } return o; }
map<string,string> parseForm(const string &body){ map<string,string> m; stringstream ss(body); string p; while(getline(ss,p,'&')){ size_t x=p.find('='); if(x!=string::npos)m[urlDecode(p.substr(0,x))]=urlDecode(p.substr(x+1)); } return m; }
int toMinutes(const string &t){ if(t.size()<5)return -1; int h=atoi(t.substr(0,2).c_str()),m=atoi(t.substr(3,2).c_str()); if(h<0||h>23||m<0||m>59)return -1; return h*60+m; }
double durationHours(const string &a,const string &b){ int x=toMinutes(a),y=toMinutes(b); if(x<0||y<0||x==y)return -1; if(y<x)y+=1440; return (y-x)/60.0; }
double peakOverlap(const string &a,const string &b){ int x=toMinutes(a),y=toMinutes(b); if(x<0||y<0)return 0; if(y<x)y+=1440; double total=0; for(int d=0;d<=1;d++){ int p1=18*60+d*1440,p2=22*60+d*1440; int lo=max(x,p1),hi=min(y,p2); if(hi>lo)total+=(hi-lo)/60.0; } return total; }
void loadCustom(){ ifstream f("data/custom_appliances.csv"); string line; getline(f,line); while(getline(f,line)){ string v[7]; stringstream ss(line); for(int i=0;i<7;i++)getline(ss,v[i],','); if(trim(v[0]).empty())continue; Appliance a; a.id=1000+(int)catalogue.size(); a.name=trim(v[0]); a.category=trim(v[1]); a.watts=atoi(v[2].c_str()); a.standby=atoi(v[3].c_str()); a.efficiency=trim(v[4]); a.priority=trim(v[5]); a.status=trim(v[6]); bool exists=false; for(auto &x:catalogue)if(x.name==a.name)exists=true; if(!exists&&a.watts>0)catalogue.push_back(a); } }
void saveCustom(const Appliance &a){ ofstream f("data/custom_appliances.csv",ios::app); ifstream check("data/custom_appliances.csv"); if(!check.good()||check.peek()==EOF)f<<"name,category,watts,standby_watts,efficiency,priority,status\n"; f<<a.name<<","<<a.category<<","<<a.watts<<","<<a.standby<<","<<a.efficiency<<","<<a.priority<<","<<a.status<<"\n"; }
void loadData(){ ifstream f("data/usage.csv"); string line; getline(f,line); while(getline(f,line)){ stringstream s(line); string v[6]; for(int i=0;i<6;i++)getline(s,v[i],','); if(v[0].empty())continue; Usage u; u.id=atoi(v[0].c_str());u.name=v[1];u.start=v[2];u.end=v[3];u.watts=atoi(v[4].c_str());u.hours=durationHours(u.start,u.end);u.daily=u.watts*u.hours/1000.0;u.peak=peakOverlap(u.start,u.end); usages.push_back(u); nextId=max(nextId,u.id+1); } }
void saveData(){ ofstream f("data/usage.csv"); f<<"id,name,start,end,watts,category\n"; for(auto &u:usages){ string cat="General"; for(auto &a:catalogue)if(a.name==u.name)cat=a.category; f<<u.id<<","<<u.name<<","<<u.start<<","<<u.end<<","<<u.watts<<","<<cat<<"\n"; } }
void loadSettings(){ ifstream f("data/settings.txt"); string s; if(f>>s)hasSolar=(s=="yes"); }
void saveSettings(){ ofstream f("data/settings.txt"); f<<(hasSolar?"yes":"no"); }
double overlapWindow(const string &a,const string &b,int from,int to){ int x=toMinutes(a),y=toMinutes(b); if(x<0||y<0)return 0; if(y<x)y+=1440; double total=0; for(int d=0;d<=1;d++){ int p1=from+d*1440,p2=to+d*1440; int lo=max(x,p1),hi=min(y,p2); if(hi>lo)total+=(hi-lo)/60.0; } return total; }
string stateJson(){ double daily=0,peak=0,dayUnits=0,nightUnits=0; for(auto &u:usages){daily+=u.daily;peak+=u.peak;double dh=overlapWindow(u.start,u.end,6*60,18*60);double nh=max(0.0,u.hours-dh);dayUnits+=u.watts*dh/1000.0;nightUnits+=u.watts*nh/1000.0;} double monthly=daily*30,dayMonthly=dayUnits*30,nightMonthly=nightUnits*30; double solarGen=hasSolar?225.0:0.0; double solarDay=hasSolar?dayMonthly*0.60:0.0; double solarNight=hasSolar?nightMonthly*0.40:0.0; double solarDemand=solarDay+solarNight; double solarScale=solarDemand>solarGen&&solarDemand>0?solarGen/solarDemand:1.0; solarDay*=solarScale; solarNight*=solarScale; double solarUsed=solarDay+solarNight; double gridDay=max(0.0,dayMonthly-solarDay),gridNight=max(0.0,nightMonthly-solarNight); double grid=gridDay+gridNight; double bill=grid*TARIFF; double savings=solarUsed*TARIFF;
 ostringstream o; o<<fixed<<setprecision(2); o<<"{\"solar\":"<<(hasSolar?"true":"false")<<",\"tariff\":"<<TARIFF<<",\"catalogue\":[";
 for(size_t i=0;i<catalogue.size();i++){if(i)o<<",";auto a=catalogue[i];o<<"{\"id\":"<<a.id<<",\"name\":\""<<jsonEscape(a.name)<<"\",\"category\":\""<<jsonEscape(a.category)<<"\",\"watts\":"<<a.watts<<",\"standby\":"<<a.standby<<",\"efficiency\":\""<<jsonEscape(a.efficiency)<<"\",\"priority\":\""<<jsonEscape(a.priority)<<"\",\"status\":\""<<jsonEscape(a.status)<<"\"}";}
 o<<"],\"entries\":["; for(size_t i=0;i<usages.size();i++){if(i)o<<",";auto u=usages[i];o<<"{\"id\":"<<u.id<<",\"name\":\""<<jsonEscape(u.name)<<"\",\"start\":\""<<u.start<<"\",\"end\":\""<<u.end<<"\",\"hours\":"<<u.hours<<",\"watts\":"<<u.watts<<",\"daily\":"<<u.daily<<",\"peak\":"<<u.peak<<"}";}
 o<<"],\"summary\":{\"daily\":"<<daily<<",\"monthly\":"<<monthly<<",\"solarGeneration\":"<<solarGen<<",\"solarUsed\":"<<solarUsed<<",\"grid\":"<<grid<<",\"bill\":"<<bill<<",\"savings\":"<<savings<<",\"peakHours\":"<<peak<<",\"dayUnits\":"<<dayMonthly<<",\"nightUnits\":"<<nightMonthly<<",\"solarDay\":"<<solarDay<<",\"gridDay\":"<<gridDay<<",\"solarNight\":"<<solarNight<<",\"gridNight\":"<<gridNight<<"}}"; return o.str(); }
string readFile(const string &path){ ifstream f(path,ios::binary); if(!f)return "Not found"; stringstream b;b<<f.rdbuf();return b.str(); }
void sendResponse(int client,const string &status,const string &type,const string &body){ string h="HTTP/1.1 "+status+"\r\nContent-Type: "+type+"\r\nContent-Length: "+to_string(body.size())+"\r\nConnection: close\r\nAccess-Control-Allow-Origin: *\r\n\r\n"; string all=h+body; send(client,all.c_str(),all.size(),0); }
int main(){ system("mkdir -p data"); loadSettings();loadCustom();loadData(); int server=socket(AF_INET,SOCK_STREAM,0); if(server<0){cerr<<"Could not create server socket\n";return 1;} int opt=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,&opt,sizeof(opt)); sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_addr.s_addr=INADDR_ANY;addr.sin_port=htons(8080); if(::bind(server,(sockaddr*)&addr,sizeof(addr))<0||listen(server,10)<0){cerr<<"Could not start server on port 8080\n";return 1;} cout<<"Home Energy C++ server running at http://localhost:8080\nPress Ctrl+C to stop.\n";
 while(true){ int client=accept(server,nullptr,nullptr); if(client<0)continue; string req;char buf[4096];int n;while((n=recv(client,buf,sizeof(buf),0))>0){req.append(buf,n);size_t h=req.find("\r\n\r\n");if(h!=string::npos){size_t cl=0;size_t cp=req.find("Content-Length:");if(cp!=string::npos){cp+=15;cl=atoi(req.c_str()+cp);}if(req.size()>=h+4+cl)break;}} size_t split=req.find("\r\n\r\n");string head=req.substr(0,split),body=split==string::npos?"":req.substr(split+4);stringstream hs(head);string method,path;hs>>method>>path;
 if(method=="GET"&&path=="/"){sendResponse(client,"200 OK","text/html; charset=utf-8",readFile("templates/index.html"));}
 else if(method=="GET"&&path=="/api/state"){sendResponse(client,"200 OK","application/json",stateJson());}
 else if(method=="POST"&&path=="/api/setup"){auto m=parseForm(body);hasSolar=(m["solar"]=="yes");saveSettings();sendResponse(client,"200 OK","application/json",stateJson());}
 else if(method=="POST"&&path=="/api/custom-appliance"){auto m=parseForm(body); Appliance a; a.id=1000+(int)catalogue.size(); a.name=trim(m["name"]);a.category=trim(m["category"]);a.watts=atoi(m["watts"].c_str());a.standby=atoi(m["standby"].c_str());a.efficiency=trim(m["efficiency"]);a.priority=trim(m["priority"]);a.status=trim(m["status"]);bool duplicate=false;for(auto &x:catalogue)if(x.name==a.name)duplicate=true;if(a.name.empty()||a.category.empty()||a.watts<=0||a.standby<0||a.name.find(',')!=string::npos||a.category.find(',')!=string::npos||duplicate){sendResponse(client,"400 Bad Request","application/json","{\"error\":\"Enter valid details. Appliance name must be unique; power must be positive.\"}");}else{catalogue.push_back(a);saveCustom(a);sendResponse(client,"200 OK","application/json",stateJson());}}
 else if(method=="POST"&&path=="/api/bot"){auto m=parseForm(body);string q=m["question"],lang=m["lang"];transform(q.begin(),q.end(),q.begin(),[](unsigned char c){return tolower(c);});string r;bool hi=(lang=="Hindi"),hing=(lang=="Hinglish");auto answer=[&](string en,string hn,string hg){return hi?hn:(hing?hg:en);};if(q.find("outage")!=string::npos||q.find("power cut")!=string::npos||q.find("light")!=string::npos||q.find("bijli")!=string::npos||q.find("electricity gone")!=string::npos){r=answer("During a power cut, switch off non-essential appliances, keep fridge/freezer doors closed, save phone and inverter battery, and use a torch. Never touch fallen wires or attempt electrical repairs. When supply returns, reconnect appliances gradually.","बिजली जाने पर गैर-ज़रूरी उपकरण बंद करें, फ्रिज का दरवाज़ा बंद रखें और फोन/इन्वर्टर की बैटरी बचाएँ। गिरे हुए तारों को न छुएँ और खुद मरम्मत न करें। बिजली आने पर उपकरण धीरे-धीरे चालू करें।","Power cut mein non-essential appliances off kar do, fridge ka door closed rakho aur phone/inverter battery save karo. Fallen wires ko touch mat karna aur khud repair mat karna. Light aane par appliances gradually ON karna.");}else if(q.find("inverter")!=string::npos||q.find("battery")!=string::npos){r=answer("To conserve backup, switch off non-essential loads, avoid high-power appliances such as heaters and kettles, and do not overload the inverter. Follow the battery manufacturer's instructions.","बैकअप बचाने के लिए गैर-ज़रूरी उपकरण बंद रखें, हीटर और केतली जैसे अधिक बिजली लेने वाले उपकरण न चलाएँ और इन्वर्टर पर अधिक लोड न डालें।","Backup bachane ke liye non-essential appliances off rakho, heater/kettle jaise high-power devices avoid karo aur inverter overload mat karo.");}else if(q.find("fridge")!=string::npos||q.find("refrigerator")!=string::npos){r=answer("Keep refrigerator and freezer doors closed. A full freezer generally stays cold longer than an empty one. If food has become warm for an unsafe period, follow food-safety guidance and discard items when in doubt.","फ्रिज और फ्रीज़र के दरवाज़े बंद रखें। खाना लंबे समय तक गर्म रहा हो तो खाद्य-सुरक्षा निर्देशों का पालन करें।","Fridge/freezer ka door band rakho. Baar-baar mat kholo. Agar food kaafi der unsafe temperature par raha ho, food safety guidance follow karo.");}else if(q.find("bill")!=string::npos||q.find("cost")!=string::npos||q.find("tariff")!=string::npos){r=answer("Estimated bill = grid units (kWh) × assumed tariff. This demo uses Rs 8 per unit; actual bills may include slab rates, fixed charges and taxes.","अनुमानित बिल = ग्रिड यूनिट (kWh) × निर्धारित दर। इस डेमो में ₹8 प्रति यूनिट माना गया है। वास्तविक बिल में अन्य शुल्क भी हो सकते हैं।","Estimated bill = grid units (kWh) × tariff. Is demo mein ₹8/unit assume kiya hai; actual bill mein fixed charges, slab rates aur taxes bhi ho sakte hain.");}else if(q.find("solar")!=string::npos){r=answer("Solar Management estimates solar and grid contribution. With solar ON, the model assumes 60% solar/40% grid during daytime and 40% solar/60% grid at night, subject to the demo generation cap. These are estimates, not live inverter readings.","सोलर मैनेजमेंट सोलर और ग्रिड का अनुमानित योगदान दिखाता है। दिन में 60% सोलर और रात में 40% सोलर माना गया है। ये वास्तविक इन्वर्टर रीडिंग नहीं हैं।","Solar ON hone par demo daytime 60% solar/40% grid aur night-time 40% solar/60% grid assume karta hai. Ye estimates hain, live inverter readings nahi.");}else if(q.find("add")!=string::npos||q.find("appliance")!=string::npos||q.find("device")!=string::npos){r=answer("Open View Appliance Data, choose an appliance, enter start and end times, then tap Add Appliance. If it is missing, use 'Can't find your appliance? Add it yourself' to save a custom appliance.","View Appliance Data खोलें, उपकरण चुनें, शुरू और खत्म होने का समय भरें और Add Appliance दबाएँ। सूची में न हो तो अपना उपकरण जोड़ने वाला विकल्प चुनें।","View Appliance Data kholo, appliance select karo, start/end time bharo aur Add Appliance dabao. List mein nahi hai toh 'Add it yourself' option use karo.");}else if(q.find("report")!=string::npos){r=answer("Open Complete Report to see your monthly energy, estimated bill, solar/grid split and appliance-wise schedule. Tap a report card or row for its calculation details.","Complete Report में मासिक खपत, अनुमानित बिल, सोलर/ग्रिड योगदान और उपकरणों का विवरण देखें। अधिक जानकारी के लिए कार्ड या पंक्ति पर टैप करें।","Complete Report kholo. Monthly units, estimated bill, solar/grid split aur appliance-wise details milengi. Calculation samajhne ke liye cards ya rows tap karo.");}else if(q.find("reduce")!=string::npos||q.find("save energy")!=string::npos||q.find("saving")!=string::npos){r=answer("Use LED lighting, switch off idle devices, avoid standby loads, maintain AC filters, and shift deferrable heavy use away from peak hours where your tariff supports it.","LED लाइट का उपयोग करें, खाली उपकरण बंद रखें, स्टैंडबाय बिजली कम करें और जहाँ संभव हो भारी उपयोग पीक समय से हटाएँ।","LED use karo, idle devices off rakho, standby load kam karo aur possible ho toh heavy usage peak hours se shift karo.");}else{r=answer("I couldn't match that question yet. Try asking about appliances, electricity bills, solar management, energy saving, reports or power cuts.","मुझे यह सवाल समझ नहीं आया। आप उपकरण, बिजली बिल, सोलर, ऊर्जा बचत, रिपोर्ट या बिजली कटौती के बारे में पूछ सकते हैं।","Ye question abhi samajh nahi aaya. Appliances, bill, solar, energy saving, report ya power cut ke baare mein pooch kar dekho.");}sendResponse(client,"200 OK","application/json","{\"reply\":\""+jsonEscape(r)+"\"}");}
 else if(method=="POST"&&path=="/api/add"){auto m=parseForm(body);string name=m["name"],start=m["start"],end=m["end"];int watts=0;for(auto &a:catalogue)if(a.name==name)watts=a.watts;double hours=durationHours(start,end);if(!watts||hours<=0||hours>24){sendResponse(client,"400 Bad Request","application/json","{\"error\":\"Please choose an appliance and enter valid start/end times.\"}");}else{Usage u;u.id=nextId++;u.name=name;u.start=start;u.end=end;u.hours=hours;u.watts=watts;u.daily=watts*hours/1000.0;u.peak=peakOverlap(start,end);usages.push_back(u);saveData();sendResponse(client,"200 OK","application/json",stateJson());}}
 else if(method=="POST"&&path=="/api/delete"){auto m=parseForm(body);int id=atoi(m["id"].c_str());usages.erase(remove_if(usages.begin(),usages.end(),[&](Usage u){return u.id==id;}),usages.end());saveData();sendResponse(client,"200 OK","application/json",stateJson());}
 else if(method=="POST"&&path=="/api/clear"){usages.clear();saveData();sendResponse(client,"200 OK","application/json",stateJson());}
 else sendResponse(client,"404 Not Found","text/plain","Not found"); close(client); }
 close(server);return 0; }
